head.script:
scwin.onpageload = function() {
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    input2.setValue(1);
    input3.setValue(2);
    input5.setValue(1);
    input6.setValue(2);
};
scwin.onpageunload = function() {};
scwin.trigger11_onclick = function(e) {
    dataList1.insertRow();
}
scwin.trigger1_onclick = function(e) {
    var deleteRowIndex = input1.getValue();
    if (deleteRowIndex) {
        dataList1.removeRow(parseInt(deleteRowIndex));
    }
}
scwin.trigger2_onclick = function(e) {
    var rowIndex = parseInt(input2.getValue());
    if (gridView1.getCellDisabled(rowIndex, 0)) {
        gridView1.setCellDisabled(rowIndex, 0, false);
    } else {
        gridView1.setCellDisabled(rowIndex, 0, true);
    }
    input1.setValue(rowIndex);
}
scwin.trigger3_onclick = function(e) {
    var rowIndex = parseInt(input3.getValue());
    if (gridView1.getCellReadOnly(rowIndex, 0)) {
        gridView1.setCellReadOnly(rowIndex, 0, false);
    } else {
        gridView1.setCellReadOnly(rowIndex, 0, true);
    }
    input1.setValue(rowIndex);
}
scwin.trigger4_onclick = function(e) {
    var deleteRowIndex = input4.getValue();
    if (deleteRowIndex) {
        dataList1.removeRow(parseInt(deleteRowIndex));
    }
}
scwin.trigger5_onclick = function(e) {
    var rowIndex = parseInt(input5.getValue());
    if (gridView1.getRowDisabled(rowIndex)) {
        gridView1.setRowDisabled(rowIndex, false);
    } else {
        gridView1.setRowDisabled(rowIndex, true);
    }
    input4.setValue(rowIndex);
}
scwin.trigger6_onclick = function(e) {
    var rowIndex = parseInt(input6.getValue());
    if (gridView1.getRowReadOnly(rowIndex)) {
        gridView1.setRowReadOnly(rowIndex, false);
    } else {
        gridView1.setRowReadOnly(rowIndex, true);
    }
    input14.setValue(rowIndex);
}
scwin.trigger7_onclick = function(e) {
    if (gridView1.options.checkAllType === "include") {
        gridView1.options.checkAllType = "exclude";
        textbox1.setValue("exclude");
    } else {
        gridView1.options.checkAllType = "include";
        textbox1.setValue("include");
    }
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById($p.id + 'gridView1_column1').children[0].indeterminate == false;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger7').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'gridView1_column1').children[0].click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "300");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
